}

{
  "diagnosis": "The agent over-weighted the most salient diagnosis and ignored the patient's current medicines, allergy history, and prior treatment failures, causing it to pick options that were either contraindicated, duplicative, or not indicated. It also treated a missing fact as present and failed to distinguish symptom relief from prophylaxis.",
  "skills": [
    {
      "id": "current_medication_interaction_scan",
      "text": "Before selecting an option, explicitly list every current medicine named by the patient and check whether any candidate would interact with it. If a candidate is known to inhibit or induce the metabolism of a current medicine, avoid it unless no safer indicated alternative exists."
    },
    {
      "id": "contraindication_from_history",
      "text": "Treat prior cancer, severe allergy, organ failure, pregnancy, and similar history as hard safety constraints. Exclude any candidate that is generally contraindicated in that history, even if it is otherwise indicated for the presenting problem."
    },
    {
      "id": "prior_treatment_failure",
      "text": "When the patient is already on a drug for the same condition and symptoms are worsening or not improving, do not choose another drug from the same mechanistic class. Prefer an agent with a different mechanism that is indicated for the same condition."
    },
    {
      "id": "indication_before_safety",
      "text": "First identify the single best-supported indication for the presenting syndrome. Then filter candidates by patient-specific safety. Do not let a safe but non-indicated drug win over an indicated drug unless the indicated drug is contraindicated."
    },
